def _nat_cmp(cls, a: Optional[str], b: Optional[str]) -> int:
    def prepare(identifier: str) -> Tuple[bool, str]:
        if not identifier.isdigit():
            return False, identifier
        if identifier.isascii():
            return True, identifier.lstrip("0") or "0"
